/* elan1 platform prototype v2 — SCREEN INVENTORY
 * window.E1_SCREENS: every screen in the platform, numbered in review order. It drives the hub (index.html), the
 * screen atlas (atlas.html), the per-screen HTML files (screens/<file>), the bottom-right screen-info pill
 * (number · type · section · prev/next · atlas grid), the "Screen notes" drawer and the command palette.
 * Generated 24 Sep 2026 from the router (window.E1.routes, 265 patterns: every one except redirects and the 404,
 * plus the parameter variants that are distinct screens). Edit here and in docs-screen-inventory.csv together.
 *
 * Fields
 *   n           1…304, the review order (surfaces in the order below; screens in door-rail order inside a surface)
 *   id          surface prefix + counter within the surface: P-01, W-03, E-12 …
 *   file        screens/<file>, = id.toLowerCase() + '-' + slug + '.html'
 *   title       the screen's name in sentence case (the rendered h1 may carry a concrete record, e.g. "Proof #4,101")
 *   route       a concrete example path; the screen file boots the SPA there (window.E1_START = route)
 *   pattern     the router pattern it renders ('*' = the designed 404 for any unknown path)
 *   surface     one of E1_SURFACES below · section: the rail item (console) or the area inside the surface
 *   type        see E1_SCREEN_TYPES below
 *   level       lowest Assurance Level at which the screen is live ('L1' | 'L2' | 'L3'). Below it the same route renders
 *               the designed "arrives at Level N" explainer, so a screen file (and every state link) should set the
 *               level first — E1.setLevel(level, {silent:true}) — before booting.
 *   states      real, clickable variants: [{label, href}] — 'Default' first. Every href was rendered headless at the
 *               screen's level: no page error, one h1, E1.match(path) resolves to this pattern, and the page text
 *               differs from Default. Mostly taken from each screen's own "View states" menu.
 *   components  E1.c components present in the rendered Default (pageHeader, table, diff, gates, rungs …); a leading
 *               siteNav / authCard / portalBand / docNav / phoneFrame / wizardFrame names the non-console layout.
 *   rules       2–5 UI rules that apply, quoted or paraphrased from the specs (honesty, dual control, refusals ₹0 …)
 *   src         source documents that shaped the screen: E01–E27, O01–O12, IM §, TM §, atlas Fig N, Brand Book,
 *               Four Doors v2.0, Channel Block, Competitor study …
 *   spec        one or two sentences: what the screen is for and what it must show
 *
 * Screen types (the parent elan1 grammar — home · list · record · queue · builder · ledger — re-cut for a
 * governed-write console, plus the entry, state and diagram types a full platform adds)
 *   home    role or door landing: pane header → stat row → attention list → recent proofs
 *   list    pane header → toolbar and filter chips (in the URL) → real table → rows open a record; logs are append-only
 *   record  one object: pane header → tabs or sections → body → audit stamp / proof link
 *   decide  a person records a decision or commits a governed write: consequence above the fold, diff, every gate,
 *           one gate button (absent, not disabled, when a blocking gate fails)
 *   wizard  a stepper; one decision per step; later steps disabled with the reason; nothing skipped
 *   doc     reference or specification reading page (developer portal, design system, verifier docs)
 *   auth    sign-in, sign-up, invitation and session pages; no console chrome
 *   system  403, 404, maintenance, offline and outage: say what happened, that nothing changed, and the way on
 *   public  marketing and trust pages of the public website
 *   mobile  360 px phone screens and channel previews (WhatsApp, voice, e-mail)
 *   map     diagram or explorer: architecture views, agent map, system map, write-path inspector, IA
 */
window.E1_SCREEN_TYPES = {
 "home": "Role or door landing: stat row, attention list, recent proofs",
 "list": "Toolbar, URL filters, a real table; rows open a record",
 "record": "One object: sections or tabs, ending in its proof or audit stamp",
 "decide": "A person records a decision or commits a governed write",
 "wizard": "A stepper, one decision per step, no skipping",
 "doc": "Reference and specification reading page",
 "auth": "Sign-in and session pages without console chrome",
 "system": "403, 404, maintenance, offline and outage states",
 "public": "Public website and trust pages",
 "mobile": "Phone screens and channel previews",
 "map": "Diagram or explorer"
};
